package com.example.campsitelottery

import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Code and documentation generated by Claude (Anthropic, Claude Opus 5.5). Estimated AI-generated share of this file: ~100%
 * Checks the policy content shown in the policy dialog.
 */
class AppPolicyTextTest {

    @Test
    fun policyHasSections() {
        assertTrue(AppPolicyText.sections.isNotEmpty())
    }

    @Test
    fun everySectionHasATitleAndBody() {
        AppPolicyText.sections.forEach { section ->
            assertFalse("Blank title", section.title.isBlank())
            assertFalse("Blank body in ${section.title}", section.body.isBlank())
        }
    }

    @Test
    fun sectionTitlesAreUnique() {
        val titles = AppPolicyText.sections.map { it.title }
        assertTrue(titles.size == titles.toSet().size)
    }

    @Test
    fun lastUpdatedIsSet() {
        assertFalse(AppPolicyText.LAST_UPDATED.isBlank())
    }
}
